SALT = "feHJ6793TJDI86DLS9D"  # 源码 0x7b2 解码值


def sha1_hex(s):
    return hashlib.sha1(s.encode("utf-8")).hexdigest()


def main():
    try:
        sys.stdout.reconfigure(errors="replace")
    except Exception:
        pass
    print(f"data 长度: {len(DATA)}")
    # 候选拼接方式（源码显示 salt + timestamp.toString() + data）
    candidates = {
        "salt+ts+data": SALT + TIMESTAMP + DATA,
        "salt+data+ts": SALT + DATA + TIMESTAMP,
        "ts+salt+data": TIMESTAMP + SALT + DATA,
        "salt+ts+data+appKey": SALT + TIMESTAMP + DATA + APP_KEY,
        "salt+ts+data+fe": SALT + TIMESTAMP + DATA + "fe",
    }
    print(f"期望 sign: {EXPECT_SIGN}")
    for name, s in candidates.items():
        h = sha1_hex(s)
        mark = "★命中" if h == EXPECT_SIGN else ""
        print(f"  {name:24s} {h} {mark}")


if __name__ == "__main__":
    main()
